{
  "status": "SUPPORTED",
  "task_summary": "Find fastening components and tool, assemble the fastening, and place tool on bench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastener",
        "entity_kind": "OBJECT",
        "function": "Supplies the material to join components",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": ["screw", "bolt", "nut", "clip"],
        "required_properties": ["compatible with target", "mechanical fastener"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "Used to apply force to secure the fastener",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": ["wrench", "screwdriver", "pliers"],
        "required_properties": ["capable of applying torque", "graspable"]
      },
      {
        "id": "target",
        "entity_kind": "FIXED_TARGET",
        "function": "The object receiving the fastening",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": ["assembly", "device", "part"],
        "required_properties": ["has mounting hole", "needs fastening"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the tool is left",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": ["desk", "table", "surface"],
        "required_properties": ["flat surface", "supportive"]
      }
    ],
    "functional_relations": [
      {
        "id": "fit",
        "relation": "fastener fits into target",
        "participant_roles": ["fastener", "target"]
      ,
        "required": true
      },
      {
        "id": "attached",
        "relation": "fastener is attached to target",
        "participant_roles": ["fastener", "target"]
      ,
        "required": true
      },
      {
        "id": "placed_on",
        "relation": "fastening_tool is placed on workbench",
        "participant_roles": ["fastening_tool", "workbench"]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "locate_parts",
        "operation": "Search for fastener and fastening_tool in scene",
        "participant_roles": ["fastener", "fastening_tool"],
        "operation_count": 1
      },
      {
        "id": "perform_fastening",
        "operation": "Attach fastener to target using tool",
        "participant_roles": ["fastener", "target", "fastening_tool"],
        "operation_count": 1
      },
      {
        "id": "deposit_tool",
        "operation": "Place fastening_tool on workbench",
        "participant_roles": ["fastening_tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastener": [],
      "fastening_tool": [
        {
          "label": "yellow and blue blocks on tray",
          "visual_description": "Small rectangular blocks on a black tray on the desk"
        }
      ],
      "target": [
        {
          "label": "items on tray",
          "visual_description": "Objects sitting on the black tray"
        }
      ],
      "workbench": [
        {
          "label": "wooden desk",
          "visual_description": "Brown wooden table surface"
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "cabinet",
        "label": "Blue cabinet",
        "visual_description": "Tall blue storage unit with closed door behind the desk",
        "reason": "Closed storage structure, likely contains spare parts or tools"
      },
      {
        "id": "drawers",
        "label": "Drawers",
        "visual_description": "Two blue drawers under the desk with closed handles",
        "reason": "Closed storage structures, likely contain tools or small components"
      }
    ],
    "inspection_order": [
      "cabinet",
      "drawers"
    ]
  },
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
